function validate([s]) {
  if (s.length < 1 || s.length > 100) return 's must have 1 to 100 characters.';
  if (!/^[01]+$/.test(s)) return 's may contain only 0 and 1.';
  if (!s.includes('1')) return 's needs at least one 1.';
  return null;
}

