function maximumOddBinaryNumber(s) {
  let ones = 0;
  for (const bit of s) {
    if (bit === '1') {
      ones++;
    }
  }
  const zeros = s.length - ones;
  return '1'.repeat(ones - 1) + '0'.repeat(zeros) + '1';
}

