function maximumOddBinaryNumber(s) {
  // Try every bit string of the same length; keep the largest odd one with the same number of ones.
  const n = s.length;
  const count = t => t.split('').filter(c => c === '1').length;
  const ones = count(s);
  let best = null;
  for (let mask = 0; mask < 2 ** n; mask++) {
    const t = mask.toString(2).padStart(n, '0');
    if (t[n - 1] !== '1' || count(t) !== ones) continue;
    if (best === null || t > best) best = t;
  }
  return best;
}

