function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 12);
  const density = rand();
  const bits = Array.from({ length: n }, () => (rand() < density ? '1' : '0'));
  bits[Math.floor(rand() * n)] = '1';
  return [bits.join('')];
}
